<script>
  // Billing cycle toggle logic
  const monthlyBtn = document.getElementById('monthly-btn');
  const annualBtn = document.getElementById('annual-btn');
  const priceElements = document.querySelectorAll('.tier-price');
  const cycleElements = document.querySelectorAll('.tier-cycle');
  const saveElements = document.querySelectorAll('.tier-save');

  function setBilling(mode) {
    if (mode === 'monthly') {
      monthlyBtn.className = 'px-6 py-2.5 rounded-full font-label-md text-label-md bg-primary-container text-on-primary shadow-md transition-all flex items-center gap-2';
      annualBtn.className = 'px-6 py-2.5 rounded-full font-label-md text-label-md text-secondary hover:text-on-surface transition-all flex items-center gap-2';
      
      priceElements.forEach(el => {
        el.textContent = el.getAttribute('data-monthly');
      });
      cycleElements.forEach(el => {
        el.textContent = '/month';
      });
      saveElements.forEach(el => {
        el.style.opacity = '0.3';
      });
    } else {
      annualBtn.className = 'px-6 py-2.5 rounded-full font-label-md text-label-md bg-primary-container text-on-primary shadow-md transition-all flex items-center gap-2';
      monthlyBtn.className = 'px-6 py-2.5 rounded-full font-label-md text-label-md text-secondary hover:text-on-surface transition-all flex items-center gap-2';
      
      priceElements.forEach(el => {
        el.textContent = el.getAttribute('data-annual');
      });
      cycleElements.forEach(el => {
        el.textContent = '/year';
      });
      saveElements.forEach(el => {
        el.style.opacity = '1';
      });
    }
  }

  if (monthlyBtn && annualBtn) {
    monthlyBtn.addEventListener('click', () => setBilling('monthly'));
    annualBtn.addEventListener('click', () => setBilling('annual'));
  }
</script></main>

